package vn.svframe.svframelib.api.crafting.event; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.recipes.*; import vn.svframe.svframelib.api.crafting.recipes.vmp.*; import net.minecraft.server.network.ServerPlayerEntity; import vn.svframe.mythiclibfabric.runtime.MythicLibEventHub; public class MythicCraftItemEvent { private final ServerPlayerEntity trigger; private final MythicRecipeInventory resultInventory; private final MythicBlueprintInventory otherInventories; private final MythicCachedResult cache; private VanillaInventoryMapping mapping; private boolean cancelled; public MythicCraftItemEvent(ServerPlayerEntity trigger,MythicRecipeInventory result,VanillaInventoryMapping mapping,MythicBlueprintInventory other,MythicCachedResult cache){this.trigger=trigger;resultInventory=result;this.mapping=mapping;otherInventories=other;this.cache=cache;} public MythicRecipeInventory getResultInventory(){return resultInventory;} public MythicBlueprintInventory getOtherInventories(){return otherInventories;} public MythicCachedResult getCache(){return cache;} public VanillaInventoryMapping getMapping(){return mapping;} public void setMapping(VanillaInventoryMapping m){mapping=m;} public ServerPlayerEntity getTrigger(){return trigger;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} public void call(){MythicLibEventHub.events().publish(this);} }
